Body:
Reproduced on `v2` at `37ff501cc6a3` with a local WebSocket server: pause the consumer, send 1,024 small frames, then resume. The current transport fails at `frame:128` instead of delivering the burst in order. No provider credentials are needed.

There is also a second fail-on-full 128-frame queue in `SessionModelTransport`, so changing only the socket adapter would leave the session path vulnerable to consumer lag. I’m checking bounded ingress buffering at the socket boundary and awaited queue offers at the async session boundary, including cancellation and connection reuse.

@neriousy, please flag if you already have a fix underway; I’m preparing a focused patch and regression evidence for this issue. This work is AI-assisted.

A patch that worked for me to extend the timeout time, made using qwen3.8-max, based on a previous [patch](https://github.com/cline/cline/discussions/11068#discussioncomment-18109688) made using same for cline:

```
<#
.SYNOPSIS
    OpenCode Desktop Timeout Patcher for LM Studio (v1.4)
.DESCRIPTION
    Fixes the hardcoded 5-minute timeout in OpenCode Desktop when using slow local models.
    Auto-detects install location (even if already patched), extracts app.asar, and injects an undici dispatcher.
#>

$ErrorActionPreference = "Stop"
$TimeoutMs   = 7200000   # 120 minutes
$PatchDir    = Join-Path $env:USERPROFILE ".opencode-patch"
$PatchTag    = "/* === opencode lmstudio timeout patch === */"
$PatchEndTag = "/* === end opencode lmstudio timeout patch === */"

function Write-Step { param($m) Write-Host "`n==> $m" -ForegroundColor Cyan }
function Write-Ok   { param($m) Write-Host "    OK: $m" -ForegroundColor Green }
function Write-Warn { param($m) Write-Host "    WARN: $m" -ForegroundColor Yellow }
function Write-Skip { param($m) Write-Host "    SKIP: $m" -ForegroundColor DarkYellow }
function Write-Err  { param($m) Write-Host "    ERR: $m" -ForegroundColor Red }

# --- 1. Locate OpenCode Desktop Installation ---
Write-Step "Locating OpenCode Desktop Installation"
$searchRoots = @(
    (Join-Path $env:LOCALAPPDATA "Programs"),
    $env:ProgramFiles,
    ${env:ProgramFiles(x86)}
) | Where-Object { $_ -and (Test-Path $_) }

$installDirs = @()
foreach ($root in $searchRoots) {
    $hits = Get-ChildItem $root -Directory -ErrorAction SilentlyContinue | 
            Where-Object { $_.Name -match 'opencode' } |
            Where-Object { 
                $resPath = Join-Path $_.FullName 'resources'
                # FIX: Check for app.asar OR app.asar.orig so it works on re-runs
                (Test-Path $resPath) -and (
                    (Test-Path (Join-Path $resPath 'app.asar')) -or 
                    (Test-Path (Join-Path $resPath 'app.asar.orig'))
                )
            }
    if ($hits) { $installDirs += $hits }
}

if ($installDirs.Count -eq 0) {
    Write-Err "OpenCode Desktop installation not found."
    exit 1
}

$installDir = $installDirs | Sort-Object { 
    $asar = Join-Path $_.FullName 'resources\app.asar'
    $orig = Join-Path $_.FullName 'resources\app.asar.orig'
    if (Test-Path $asar) { (Get-Item $asar).LastWriteTime } elseif (Test-Path $orig) { (Get-Item $orig).LastWriteTime } else { 0 }
} -Descending | Select-Object -First 1

$resDir = Join-Path $installDir.FullName "resources"
$asarFile = Join-Path $resDir "app.asar"
$appDir = Join-Path $resDir "app"

Write-Ok "Found: $($installDir.FullName)"

# --- 2. Extract app.asar ---
Write-Step "Extracting app.asar"
if (Test-Path $appDir) {
    Write-Skip "app\ folder already exists."
} else {
    if (-not (Test-Path $asarFile)) {
        Write-Err "app\ folder missing and app.asar not found to extract from."
        exit 1
    }
    if (-not (Get-Command npx -ErrorAction SilentlyContinue)) {
        Write-Err "npx not found. Please install Node.js."
        exit 1
    }
    Push-Location $resDir
    try {
        & npx --yes "@electron/asar" extract "app.asar" "app"
        if ($LASTEXITCODE -ne 0) { throw "Extraction failed" }
    } finally { Pop-Location }
    Write-Ok "Extracted to: $appDir"
}

$appPkg = Join-Path $appDir "package.json"
if (-not (Test-Path $appPkg)) {
    Write-Err "app/package.json missing after extraction."
    exit 1
}

$asarBackup = Join-Path $resDir "app.asar.orig"
if (Test-Path $asarFile) {
    if (-not (Test-Path $asarBackup)) {
        Rename-Item $asarFile $asarBackup
        Write-Ok "Backed up: app.asar -> app.asar.orig"
    } else {
        Remove-Item $asarFile -Force -ErrorAction SilentlyContinue
    }
}

$unpackedDir = Join-Path $resDir "app.asar.unpacked"
if (Test-Path $unpackedDir) {
    Copy-Item "$unpackedDir\*" $appDir -Recurse -Force -ErrorAction SilentlyContinue
}

